Q: Using reduce() to find the second largest element in the array A: <p>This is most simple way to find second largest number in array. Also works for 3rd, 4th.......... just need to campare it with previous one.</p>
<p>const number = [1, 2, 9, 3, 5, 7, 0];</p>
<pre class="lang-js prettyprint-override"><code>const max = number.reduce((acc, curr) =&gt; (curr &gt; acc ? curr : acc));// find max number first
const second = number.reduce((acc, curr)=&gt; {
   return curr &gt; acc &amp;&amp; curr &lt; max ? curr : acc
})// find second highest using max number
const third  = number.reduce((acc, curr)=&gt; {
   return curr &gt; acc  &amp;&amp; curr &lt; second? curr : acc
})// similary 3rd, 4th.... using the highest found in array. 
console.log(max);
console.log(second);
console.log(third);
</code></pre>
